/// Resolves Windows native system-call numbers per Windows build and ISA.
/// Numbers are taken from the j00ru Windows System Call Tables (ntoskrnl).
[<RequireQualifiedAccess>]
module WindowsSyscall =
  /// x64 SSNs on Windows XP (SP1).
  let private x64WinXPSP1 = function
    | 0 -> 0x0060
    | 1 -> 0x0061
    | 2 -> 0x0026
    | 3 -> 0x0062
    | 4 -> 0x0056
    | 5 -> 0x0063
