  /// Gets the system-call number for the given syscall on the given Windows
  /// build and ISA (x86 or x64). Raises UnhandledSyscallException if the
  /// syscall is absent on that build/ISA or the ISA is neither x86 nor x64.
  [<CompiledName "ToNumber">]
  let toNumber (build: WindowsBuild) isa (syscall: WindowsSyscall) =
    match isa with
    | X64 -> x64Fn build (int syscall)
    | X86 -> x86Fn build (int syscall)
    | _ -> raise UnhandledSyscallException
